//! 📨️ Original emitted values and metadata move under the actual caller before mounted publication owns them.
use semio_framework_plugin_decl_app::ArtifactApp;
use semio_framework_plugin_decl_emission::{ActionMeta,Emit};
use semio_framework_job::{OriginalCallerSourceLoan,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,StepContext,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use std::mem::{ManuallyDrop,size_of};
/// 📦️ The real producer retains this complete input slot when capture is denied.
#[derive(semio_framework_value::RetireOwned)]
#[value(send_only)]
pub struct OriginalEmissionInput<A:ArtifactApp>{pub verb:String,pub meta:ActionMeta,pub emit:Emit<A::Mutation,A::ConfigMutation,A::DraftMutation>}
/// 🧺️ A producer slot lives beside the command route, independently of its mounted consumer.
pub struct OriginalEmissionSource<A:ArtifactApp>{pub input:ManuallyDrop<Option<OriginalEmissionInput<A>>>,verb:ManuallyDrop<Option<String>>,offset:usize,verb_source:Option<(usize,usize)>,retirement:RetainedCloneClose,body:Option<usize>,caller:ManuallyDrop<Option<OriginalCallerSourceLoan>>,binding:Option<OriginalSourceBinding>,decoder:Option<(u64,u64)>}
impl<A:ArtifactApp> Default for OriginalEmissionSource<A>{fn default()->Self{Self{input:ManuallyDrop::new(None),verb:ManuallyDrop::new(None),offset:0,verb_source:None,retirement:Default::default(),body:None,caller:ManuallyDrop::new(None),binding:None,decoder:None}}}
impl<A:ArtifactApp> OriginalEmissionSource<A>{
 /// 📥️ An empty gesture moves the original verb and metadata only inside its paid producer action.
 pub fn admit_empty(&mut self,verb:&str,meta:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.body.is_none(){let d=fixed::<Self>();let body=cx.retained_grant().maximum_copy_bytes;let binding=OriginalSourceBinding::borrow(cx);let mut done=None;admit_original_construction(cx,&mut done,original(d),|control|{self.body=Some(body);self.binding=Some(binding);self.decoder=Some((control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(refusal)?));Ok(((),progress(d)))})?;return Ok(false)}self.validate(cx)?;if self.input.is_some(){return Ok(true)}if self.caller.is_none(){let Some(caller)=cx.original_source_parent()?.admit_loan(cx)?else{return Ok(false)};*self.caller=Some(caller);return Ok(false)}if meta.is_none(){return Err(refusal().into())}let source=(verb.as_ptr()as usize,verb.len());if self.verb_source.is_some_and(|original|original!=source){return Err(refusal().into())}if self.verb.is_none(){let d=RetirementDemand{capacity_bytes:verb.len(),..fixed::<Option<String>>()};admit_original_construction(cx,&mut self.verb,original(d),|control|{control.charge(d.capacity_bytes)?;self.verb_source=Some(source);Ok((String::with_capacity(verb.len()),progress(d)))})?;return Ok(false)}if self.offset<verb.len(){let mut end=(self.offset+64).min(verb.len());while !verb.is_char_boundary(end){end-=1}let d=RetirementDemand{copy_bytes:end-self.offset+2*size_of::<usize>(),depth:1,..Default::default()};let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{self.verb.as_mut().unwrap().push_str(&verb[self.offset..end]);self.offset=end;Ok(((),progress(d)))})?;return Ok(false)}let d=fixed::<(OriginalEmissionInput<A>,OriginalEmissionInput<A>)>();admit_original_construction(cx,&mut self.input,original(d),|_|Ok((OriginalEmissionInput{verb:self.verb.take().unwrap(),meta:meta.take().unwrap(),emit:Emit::default()},progress(d))))}
 fn validate_source(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.is_some_and(|binding|binding.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(refusal().into())}Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{self.validate_source(cx)?;if let Some(caller)=self.caller.as_ref(){caller.validate_context(cx)?}Ok(())}
 pub fn pending(&self)->bool{self.body.is_some()||self.input.is_some()||self.verb.is_some()||self.caller.is_some()||!self.retirement.is_empty()}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(self.body.ok_or_else(refusal)?)}if self.input.is_some(){return self.retirement.next_owner_demands::<OriginalEmissionInput<A>>(true,&None,self.body.ok_or_else(refusal)?)}if self.verb.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,self.body.ok_or_else(refusal)?)}if let Some(caller)=self.caller.as_ref(){return Ok(caller.retirement_demands())}if self.body.is_some(){return Ok(fixed::<Self>())}Ok(Default::default())}
 /// 🪦️ The same original caller closes the retained input before its real loan returns.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.pending(){return Ok(true)}self.validate_source(cx)?;if self.input.is_none()&&self.verb.is_none()&&self.retirement.is_empty(){if let Some(caller)=self.caller.as_mut(){caller.close_step(cx.original_source_parent()?,cx)?;if caller.terminal_is_empty(){self.caller.take();}return Ok(false)}}let d=self.close_demands()?;close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body.unwrap())?.step(g)}if self.input.is_some(){return Ok(self.retirement.begin_granted(&mut self.input,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}if self.verb.is_some(){return Ok(self.retirement.begin_granted(&mut self.verb,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}self.body=None;self.binding=None;self.decoder=None;self.offset=0;self.verb_source=None;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(!self.pending())}
}
impl<A:ArtifactApp> Drop for OriginalEmissionSource<A>{fn drop(&mut self){assert!(std::thread::panicking()||!self.pending(),"original emission producer requires paid physical closure")}}
/// 🪪️ The incoming caller loan stays beside its original metadata and emitted bodies until their paid handoff or close.
pub struct OriginalEmissionCapture<A:ArtifactApp>{body:usize,binding:Option<OriginalSourceBinding>,decoder:(u64,u64),caller:ManuallyDrop<Option<OriginalCallerSourceLoan>>,input:ManuallyDrop<Option<OriginalEmissionInput<A>>>,retirement:RetainedCloneClose,closing:bool}
fn refusal()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original emission changed its actual source caller or lifecycle")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<A:ArtifactApp> OriginalEmissionCapture<A>{
 /// 📏️ Seats only the fixed empty source cursor before any original body moves.
 pub fn birth_demands()->RetirementDemand{fixed::<(Self,Self)>()}
 /// 🎟️ A denied cursor birth leaves every input owner with its actual producer.
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Self>)->Result<bool,OriginalTurnFailure>{if output.is_some(){return Err(refusal().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::birth_demands();admit_original_construction(cx,output,original(d),|control|{let recipient=control.retirement_recipient_identity().ok_or_else(refusal)?;Ok((Self{body,binding:Some(binding),decoder:(control.ledger_identity(),recipient),caller:ManuallyDrop::new(None),input:ManuallyDrop::new(None),retirement:Default::default(),closing:false},progress(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.is_some_and(|binding|binding.matches(cx))||cx.native_receiving_identity()!=Some(self.decoder){return Err(refusal().into())}if let Some(caller)=self.caller.as_ref(){caller.validate_context(cx)?;}Ok(())}
 /// 📐️ Moves only original field headers; payload and ViewModel allocations retain their exact backing.
 pub fn input_demands()->RetirementDemand{fixed::<(OriginalEmissionInput<A>,OriginalEmissionInput<A>)>()}
 /// 📥️ Receives the actual producer slot only after its original caller loan has been funded.
 pub fn receive(&mut self,input:&mut Option<OriginalEmissionInput<A>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(refusal().into())}if self.input.is_some(){return if input.is_none(){Ok(true)}else{Err(refusal().into())}}if self.caller.is_none(){let Some(caller)=cx.original_source_parent()?.admit_loan(cx)?else{return Ok(false)};*self.caller=Some(caller);return Ok(false)}if input.is_none(){return Err(refusal().into())}let d=Self::input_demands();admit_original_construction(cx,&mut self.input,original(d),|_|Ok((input.take().unwrap(),progress(d))))}
 /// 👁️ Reads the exact retained original without cloning a ViewModel, operation or text field.
 pub fn borrow(&self)->Option<&OriginalEmissionInput<A>>{self.input.as_ref()}
 /// 🎯️ The original funded capture fixes its body policy before any close selection.
 pub fn original_body(&self)->usize{self.body}
 /// 📤️ The actual mounted constructor receives the original bodies and caller loan inside its admitted construction action.
 pub fn handoff_into<T>(&mut self,cx:&mut StepContext<'_>,output:&mut Option<T>,demand:RetirementDemand,build:impl FnOnce(OriginalEmissionInput<A>,OriginalCallerSourceLoan,OriginalSourceBinding)->(T,RetainedCloneProgress))->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing||self.input.is_none()||self.caller.is_none()||output.is_some(){return Err(refusal().into())}let minimum=2*size_of::<OriginalEmissionInput<A>>()+size_of::<OriginalCallerSourceLoan>()+size_of::<OriginalSourceBinding>();if demand.copy_bytes<minimum||demand.depth==0{return Err(refusal().into())}admit_original_construction(cx,output,original(demand),|_|{let input=self.input.take().unwrap();let caller=self.caller.take().unwrap();let binding=self.binding.take().unwrap();Ok(build(input,caller,binding))})}
 /// 📏️ Quotes the actual input retirement or original caller return without mutating its selection.
 pub fn close_demands(&self,_body:usize)->Result<RetirementDemand,ValueError>{let body=self.body;if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.input.is_some(){return self.retirement.next_owner_demands::<OriginalEmissionInput<A>>(true,&None,body)}if let Some(caller)=self.caller.as_ref(){return Ok(caller.retirement_demands())}if self.binding.is_some(){return Ok(fixed::<Option<OriginalSourceBinding>>())}Ok(Default::default())}
 /// ♻️ Cancellation closes the original metadata and emission before returning the same caller loan.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}self.validate(cx)?;self.closing=true;if !self.retirement.is_empty(){let selected=self.retirement.select(self.body)?;let d=selected.demands();close_original_retained_step(cx,d,|grant|selected.step(grant))?;return Ok(false)}if self.input.is_some(){let d=self.retirement.next_owner_demands::<OriginalEmissionInput<A>>(true,&None,self.body)?;close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.input,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}if let Some(caller)=self.caller.as_mut(){caller.close_step(cx.original_source_parent()?,cx)?;if caller.terminal_is_empty(){self.caller.take();}return Ok(false)}let d=fixed::<Option<OriginalSourceBinding>>();close_original_retained_step(cx,d,|_|{self.binding=None;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(self.terminal_is_empty())}
 /// 🈳️ Both the original payload and its actual caller authority have returned.
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.caller.is_none()&&self.input.is_none()&&self.retirement.is_empty()}
}
impl<A:ArtifactApp> Drop for OriginalEmissionCapture<A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original emission capture retains source bodies or caller custody");}}

fn decimal_bytes(value:u64,bytes:&mut [u8;20])->&str{let mut value=value;let mut offset=20;loop{offset-=1;bytes[offset]=b'0'+(value%10)as u8;value/=10;if value==0{break}}std::str::from_utf8(&bytes[offset..]).unwrap()}
/// 🧾️ The admission receipt identifies the actual mounted operation whose original outbox owns mutation delivery.
pub fn admit_original_emission_receipt(operation:semio_framework_job::Operation,cx:&mut StepContext<'_>,output:&mut Option<semio_framework::kernel::InvocationResult>)->Result<bool,OriginalTurnFailure>{
 use semio_framework::kernel::{InvocationResult,InvocationId,UndoGroup,UiDirtyScope};use semio_framework_value::DslValue;
 let mut id_bytes=[0;20];let mut generation_bytes=[0;20];let id=decimal_bytes(operation.operation.0,&mut id_bytes);let generation=decimal_bytes(operation.generation.0,&mut generation_bytes);let invocation_len="operation::".len()+id.len()+generation.len();let text_bytes="operationId".len()+"generation".len()+id.len()+generation.len()+invocation_len;let capacity=2*size_of::<(String,DslValue)>()+text_bytes;let d=RetirementDemand{copy_bytes:2*size_of::<InvocationResult>()+text_bytes+2*size_of::<(String,DslValue)>(),capacity_bytes:capacity,depth:1,..Default::default()};
 admit_original_construction(cx,output,original(d),|_|{let mut invocation=String::with_capacity(invocation_len);invocation.push_str("operation:");invocation.push_str(id);invocation.push(':');invocation.push_str(generation);let mut fields=Vec::with_capacity(2);fields.push(("operationId".to_owned(),DslValue::String(id.to_owned())));fields.push(("generation".to_owned(),DslValue::String(generation.to_owned())));let result=InvocationResult{output:DslValue::Object(fields),mutations:Vec::new(),inverse_group:UndoGroup{invocation_id:InvocationId(invocation),mutations:Vec::new(),inverse_mutations:Vec::new(),member_edits:Vec::new()},diagnostics:Vec::new(),requested_effects:Vec::new(),events:Vec::new(),ui_scope:UiDirtyScope::None,history_patch:None};Ok((result,progress(d)))})
}

/// 🪪️ A fixed admission receipt retains the same original source and receiving recipient until handoff.
#[derive(Clone,Copy)]
pub struct OriginalEmissionReceipt{operation:semio_framework_job::Operation,binding:semio_framework_job::OriginalSourceBinding,decoder:(u64,u64)}
impl OriginalEmissionReceipt{
 pub fn capture(operation:semio_framework_job::Operation,cx:&semio_framework_job::StepContext<'_>)->Result<Self,semio_framework_job::OriginalTurnFailure>{let decoder=cx.native_receiving_identity().ok_or_else(||semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original emission receipt has no receiving recipient"))?;Ok(Self{operation,binding:semio_framework_job::OriginalSourceBinding::borrow(cx),decoder})}
 pub fn operation(self,cx:&semio_framework_job::StepContext<'_>)->Result<semio_framework_job::Operation,semio_framework_job::OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original emission receipt changed its source or receiving recipient").into())}Ok(self.operation)}
}
